/// Conservative: does this block contain ANY write through a deref LHS
/// (`*place = ..` or `*place op= ..`)? Used to fail-close deref writes in
/// non-inline-execution blocks (async/try/const) where neither inline SSA nor
/// exit-havoc modeling is correct.
fn block_contains_deref_write(block: &syn::Block) -> bool {
    struct Finder {
        found: bool,
    }
    fn is_deref_lhs(e: &Expr) -> bool {
        let mut cur = e;
        loop {
            match cur {
                Expr::Paren(p) => cur = &p.expr,
                Expr::Group(g) => cur = &g.expr,
                Expr::Unary(u) if matches!(u.op, syn::UnOp::Deref(_)) => return true,
                _ => return false,
            }
        }
    }
    impl<'ast> Visit<'ast> for Finder {
        fn visit_expr_assign(&mut self, assign: &'ast syn::ExprAssign) {
            if is_deref_lhs(&assign.left) {
                self.found = true;
            }
            syn::visit::visit_expr_assign(self, assign);
        }
        fn visit_expr_binary(&mut self, binary: &'ast syn::ExprBinary) {
            if compound_assignment_value_op(&binary.op).is_some() && is_deref_lhs(&binary.left) {
                self.found = true;
            }
            syn::visit::visit_expr_binary(self, binary);
        }
    }
    let mut finder = Finder { found: false };
    finder.visit_block(block);
    finder.found
}

fn unsupported_deref_assignment_error(target: &Expr) -> TrustVcError {
    TrustVcError::Encoding {
        context: "extract body assertions",
        detail: format!(
            "assignment through a dereferenced reference is unsupported in vc_extraction: `{}`. \
             TrustVc only models direct writes through aliases created by `&mut local` or by \
             direct scalar mutable-reference parameters when the referent has scoped state at \
             borrow time; non-scalar parameter-derived aliases, reborrows, tuple/index/nested \
             projections, and nested mutable-reference places are rejected to avoid \
             silently treating aliased mutable state as unchanged.",
            target.to_token_stream()
        ),
    }
}

/// Write-arm refusal for `*alias = <rhs>` through an Option payload alias
/// whose right-hand side is not a literal of the payload type.
fn option_payload_write_refusal(place: &Expr, rhs: &Expr) -> TrustVcError {
    TrustVcError::Encoding {
        context: "extract body assertions",
        detail: format!(
            "{OPTION_PAYLOAD_ALIAS_REFUSAL}{OPTION_PAYLOAD_ERR_WRITE_VALUE}: `{} = {}`",
            place.to_token_stream(),
            rhs.to_token_stream()
        ),
    }
}

/// Read-arm refusal for a use of a tracked `&mut` holder container that the
/// model does not cover. Used ONLY by the read arms; the write funnel keeps
/// the pinned deref / projection texts.
fn unsupported_mut_ref_holder_use_error(expr: &Expr) -> TrustVcError {
    TrustVcError::Encoding {
        context: "extract body assertions",
        detail: format!(
            "use of a tuple/struct holding a mutable reference is unsupported in vc_extraction: `{}`. \
             TrustVc models such a local only as `*holder.m = value` writes, `*holder.m` reads, \
             plain-component reads `holder.m`, and one same-block move `let moved = holder;`; a \
             bare use, a reference to it or to a component, a call/method argument, a closure \
             capture, a component rebind, a deref of a plain component, or any use after a move \
             is rejected to avoid silently treating the borrowed roots as unchanged.",
            expr.to_token_stream()
        ),
    }
}

/// The root of a projected compound-assignment place (`s.f`, `p.1`, `v[i].f`,
/// `w.p.f`), peeling field / index / paren / group layers.
enum ProjectedPlaceRoot {
    /// A single-segment path binding (`s`, `self`).
    Binding(String),
    /// A tuple / struct / array literal: the write lands in a discarded temporary.
    TemporaryLiteral,
    /// Anything else (a dereference, call, method call, block, multi-segment path).
    Other,
}

fn projected_place_root(expr: &Expr) -> ProjectedPlaceRoot {
    match strip_place_wrappers(expr) {
        Expr::Field(field) => projected_place_root(&field.base),
        Expr::Index(index) => projected_place_root(&index.expr),
        Expr::Tuple(_) | Expr::Struct(_) | Expr::Array(_) | Expr::Repeat(_) => {
            ProjectedPlaceRoot::TemporaryLiteral
        }
        path @ Expr::Path(_) => match expr_path_ident(path) {
            Some(name) => ProjectedPlaceRoot::Binding(name),
            None => ProjectedPlaceRoot::Other,
        },
        _ => ProjectedPlaceRoot::Other,
    }
}

/// `(e0, e1, ..).i` (paren / group wrapped anywhere): the tuple literal and its
/// `i`-th element. `None` for any other place shape or an out-of-range index.
fn temporary_tuple_literal_field(expr: &Expr) -> Option<(&Expr, &Expr)> {
    let Expr::Field(field) = strip_place_wrappers(expr) else {
        return None;
    };
    let syn::Member::Unnamed(index) = &field.member else {
        return None;
    };
    let tuple = strip_place_wrappers(&field.base);
    let Expr::Tuple(literal) = tuple else {
        return None;
    };
    let element = literal.elems.iter().nth(index.index as usize)?;
    Some((tuple, element))
}

